<?php declare(strict_types=1); namespace Smartresponsor\Infrastructure\Decorator; use Smartresponsor\ServiceInterface\LocatorInterface; use Smartresponsor\DomainInterface\LoggerInterface; use Smartresponsor\Domain\AddressData; use Smartresponsor\Domain\GeoPoint; final class TracingLocator implements LocatorInterface{ public function __construct(private LocatorInterface $i, private LoggerInterface $l){} public function normalize(string $r): AddressData{ $t=microtime(true); try{ $x=$this->i->normalize($r); $this->l->info('normalize.ok',['ms'=>(int)((microtime(true)-$t)*1000)]); return $x; }catch(\Throwable $e){ $this->l->error('normalize.fail',['err'=>$e->getMessage()]); throw $e; }} public function geocode(AddressData $a): GeoPoint{ $t=microtime(true); try{ $x=$this->i->geocode($a); $this->l->info('geocode.ok',['ms'=>(int)((microtime(true)-$t)*1000)]); return $x; }catch(\Throwable $e){ $this->l->error('geocode.fail',['err'=>$e->getMessage()]); throw $e; }} public function reverse(GeoPoint $p): AddressData{ $t=microtime(true); try{ $x=$this->i->reverse($p); $this->l->info('reverse.ok',['ms'=>(int)((microtime(true)-$t)*1000)]); return $x; }catch(\Throwable $e){ $this->l->error('reverse.fail',['err'=>$e->getMessage()]); throw $e; }} }